UPDATE ai_device_wake_word
status = #{status}, desired_word = #{values.desiredWord}, active_word = #{values.activeWord}, active_version = #{values.activeVersion}, candidate_path = #{values.candidatePath}, candidate_token = #{values.candidateToken}, candidate_sha256 = #{values.candidateSha256}, candidate_size = #{values.candidateSize}, last_error_code = #{values.lastErrorCode}, last_error_message = #{values.lastErrorMessage}, capable = #{values.capable}, capability_reason = #{values.capabilityReason}, chip_model = #{values.chipModel}, assets_partition_size = #{values.assetsPartitionSize}, layout_version = #{values.layoutVersion}, slot_size = #{values.slotSize}, lock_token = #{values.lockToken}, lock_until = #{values.lockUntil}, updated_at = NOW()
WHERE device_id = #{deviceId} AND desired_version = #{desiredVersion} AND lock_token = #{values.lockToken}

UPDATE ai_device_wake_word
SET lock_token = #{lockToken}, lock_until = #{lockUntil}, updated_at = NOW()
WHERE device_id = #{deviceId}
  AND desired_version = #{desiredVersion}
  AND (lock_until IS NULL OR lock_until < NOW())

UPDATE ai_device_wake_word
SET lock_token = NULL, lock_until = NULL, updated_at = NOW()
WHERE device_id = #{deviceId}
  AND desired_version = #{desiredVersion}
  AND lock_token = #{lockToken}
